// The hg DDS types generated by OUR CycloneDDS 0.10.2 build from the reconstructed IDL (rt/idl/src) - built only
// with -DR1RT_WITH_CYCLONEDDS=ON (rt/idl/build_cyclonedds.sh). Checks:
//  1. the generated C++ equals Unitree's generated headers (unitree_sdk2 @63096d0) except for the banner and the
//     include-guard name - including the XTypes type-map / type-info blobs (the type identifiers DDS peers match);
//  2. the generated classes have the CRC-image layout of hg_msgs.hpp, so the CRC unitree_sdk2 computes over the
//     message object ((uint32_t*)&msg) equals r1rt::hg_crc;
//  3. a CDR (XCDR1, little-endian) round trip keeps every field and the CRC; the wire offsets differ from the
//     CRC image (printed), which is why the DDS layer copies fields instead of sending the struct image.
#include <gtest/gtest.h>

#include <cstdint>
#include <cstring>
#include <fstream>
#include <new>
#include <sstream>
#include <string>
#include <vector>

#include "org/eclipse/cyclonedds/core/cdr/basic_cdr_ser.hpp"
#include "r1rt/crc32.hpp"
#include "r1rt/hg_msgs.hpp"
#include "unitree/idl/hg/HandState_.hpp"
#include "unitree/idl/hg/LowCmd_.hpp"
#include "unitree/idl/hg/LowState_.hpp"

namespace {

namespace cdr = org::eclipse::cyclonedds::core::cdr;
namespace uhg = unitree_hg::msg::dds_;

// The body of a generated header: without the 9-line banner and the include-guard lines.
std::vector<std::string> body(const std::string& path) {
  std::ifstream f(path);
  std::vector<std::string> out;
  std::string line;
  int n = 0;
  while (std::getline(f, line)) {
    if (++n <= 9) continue;
    if (line.rfind("#ifndef DDSCXX_", 0) == 0 || line.rfind("#define DDSCXX_", 0) == 0 ||
        line.rfind("#endif // DDSCXX_", 0) == 0)
      continue;
    out.push_back(line);
  }
  return out;
}

TEST(HgDds, GeneratedTypesEqualUnitrees) {
  for (const char* n : {"MotorCmd_", "LowCmd_", "MotorState_", "IMUState_", "LowState_", "PressSensorState_",
                        "HandCmd_", "HandState_"}) {
    const auto ours = body(std::string(R1RT_HG_GEN_DIR) + "/" + n + ".hpp");
    const auto unitree = body(std::string(R1RT_UNITREE_HG_DIR) + "/" + n + ".hpp");
    ASSERT_GT(ours.size(), 50u) << n;
    EXPECT_EQ(ours, unitree) << n << ": the reconstructed IDL does not regenerate Unitree's type";
  }
}

uhg::LowCmd_ to_dds(const r1rt::hg::LowCmd& m) {
  uhg::LowCmd_ d;
  d.mode_pr(m.mode_pr);
  d.mode_machine(m.mode_machine);
  for (int i = 0; i < r1rt::hg::kNumMotorSlots; ++i) {
    auto& c = d.motor_cmd()[static_cast<std::size_t>(i)];
    c.mode(m.motor_cmd[i].mode);
    c.q(m.motor_cmd[i].q);
    c.dq(m.motor_cmd[i].dq);
    c.tau(m.motor_cmd[i].tau);
    c.kp(m.motor_cmd[i].kp);
    c.kd(m.motor_cmd[i].kd);
    c.reserve(m.motor_cmd[i].reserve);
  }
  for (std::size_t i = 0; i < 4; ++i) d.reserve()[i] = m.reserve[i];
  d.crc(m.crc);
  return d;
}

r1rt::hg::LowCmd from_dds(const uhg::LowCmd_& d) {
  r1rt::hg::LowCmd m;
  r1rt::hg::clear(m);
  m.mode_pr = d.mode_pr();
  m.mode_machine = d.mode_machine();
  for (int i = 0; i < r1rt::hg::kNumMotorSlots; ++i) {
    const auto& c = d.motor_cmd()[static_cast<std::size_t>(i)];
    // field by field: assigning a temporary aggregate copies ITS indeterminate padding over clear()'s zeros (GCC does;
    // the byte-wise memcmp below then fails - session 6, the Linux build check; the CRC image never includes padding)
    auto& o = m.motor_cmd[i];
    o.mode = c.mode();
    o.q = c.q();
    o.dq = c.dq();
    o.tau = c.tau();
    o.kp = c.kp();
    o.kd = c.kd();
    o.reserve = c.reserve();
  }
  for (std::size_t i = 0; i < 4; ++i) m.reserve[i] = d.reserve()[i];
  m.crc = d.crc();
  return m;
}

r1rt::hg::LowCmd sample_cmd() {
  r1rt::hg::LowCmd m;
  r1rt::hg::clear(m);
  m.mode_machine = 1;
  for (int i = 0; i < r1rt::hg::kNumMotorSlots; ++i) {
    m.motor_cmd[i].mode = static_cast<std::uint8_t>(i % 2);
    m.motor_cmd[i].q = 0.01f * static_cast<float>(i);
    m.motor_cmd[i].dq = -0.5f;
    m.motor_cmd[i].tau = 1.25f;
    m.motor_cmd[i].kp = 84.302f;
    m.motor_cmd[i].kd = 5.367f;
    m.motor_cmd[i].reserve = 0x01020304u + static_cast<std::uint32_t>(i);
  }
  m.reserve[2] = 7;
  m.crc = r1rt::hg_crc(m);
  return m;
}

// What unitree_sdk2 does before writing: crc32_core((uint32_t*)&msg, (sizeof(msg) >> 2) - 1) over the object.
TEST(HgDds, ClassLayoutIsTheCrcImage) {
  static_assert(sizeof(uhg::LowCmd_) == sizeof(r1rt::hg::LowCmd), "LowCmd_ object = 1004 B");
  static_assert(sizeof(uhg::LowState_) == sizeof(r1rt::hg::LowState), "LowState_ object = 2092 B");
  const r1rt::hg::LowCmd m = sample_cmd();
  alignas(uhg::LowCmd_) unsigned char buf[sizeof(uhg::LowCmd_)];
  std::memset(buf, 0, sizeof(buf));  // zero padding, as the CRC image assumes
  auto* d = new (buf) uhg::LowCmd_(to_dds(m));
  std::uint8_t img[sizeof(r1rt::hg::LowCmd)];
  r1rt::hg::crc_image(m, img);
  EXPECT_EQ(std::memcmp(buf, img, sizeof(img)), 0) << "generated class layout != CRC image";
  std::uint32_t words[sizeof(uhg::LowCmd_) / 4];
  std::memcpy(words, buf, sizeof(words));
  EXPECT_EQ(r1rt::crc32_core_ref(words, (sizeof(uhg::LowCmd_) >> 2) - 1), r1rt::hg_crc(m));
  d->~LowCmd_();
}

TEST(HgDds, CdrRoundTripKeepsFieldsAndCrc) {
  const r1rt::hg::LowCmd m = sample_cmd();
  const uhg::LowCmd_ d = to_dds(m);
  cdr::basic_cdr_stream sz(cdr::endianness::little_endian);
  ASSERT_TRUE(cdr::move(sz, d, false));
  const std::size_t n = sz.position();
  std::vector<char> wire(n);
  cdr::basic_cdr_stream w(cdr::endianness::little_endian);
  w.set_buffer(wire.data(), n);
  ASSERT_TRUE(cdr::write(w, d, false));
  ASSERT_EQ(w.position(), n);
  uhg::LowCmd_ back;
  cdr::basic_cdr_stream r(cdr::endianness::little_endian);
  r.set_buffer(wire.data(), n);
  ASSERT_TRUE(cdr::read(r, back, false));
  EXPECT_TRUE(back == d);
  const r1rt::hg::LowCmd m2 = from_dds(back);
  EXPECT_EQ(std::memcmp(&m2, &m, sizeof(m)), 0);
  EXPECT_EQ(r1rt::hg_crc(m2), m.crc);
  // Where motor_cmd[0].q lands on the wire vs in the CRC image (the layouts differ: CDR aligns members, not structs).
  float q0 = 0.0f;
  std::size_t wire_q0 = 0;
  for (std::size_t off = 0; off + 4 <= n; ++off) {  // the first occurrence of motor_cmd[1].q = 0.01f after mode bytes
    std::memcpy(&q0, wire.data() + off, 4);
    if (q0 == 0.01f) {
      wire_q0 = off;
      break;
    }
  }
  std::printf("[ info ] LowCmd_ CDR body %zu B (CRC image %zu B); motor_cmd[1].q at wire byte %zu, image byte %zu\n",
              n, sizeof(r1rt::hg::LowCmd), wire_q0,
              offsetof(r1rt::hg::LowCmd, motor_cmd) + sizeof(r1rt::hg::MotorCmd) + offsetof(r1rt::hg::MotorCmd, q));
}

TEST(HgDds, HandStateIsVariableLength) {
  uhg::HandState_ h;
  h.motor_state().resize(7);
  h.press_sensor_state().resize(9);
  h.press_sensor_state()[3].pressure()[5] = 123.0f;
  cdr::basic_cdr_stream sz(cdr::endianness::little_endian);
  ASSERT_TRUE(cdr::move(sz, h, false));
  std::vector<char> wire(sz.position());
  cdr::basic_cdr_stream w(cdr::endianness::little_endian);
  w.set_buffer(wire.data(), wire.size());
  ASSERT_TRUE(cdr::write(w, h, false));
  uhg::HandState_ back;
  cdr::basic_cdr_stream r(cdr::endianness::little_endian);
  r.set_buffer(wire.data(), wire.size());
  ASSERT_TRUE(cdr::read(r, back, false));
  EXPECT_TRUE(back == h);
  std::printf("[ info ] Dex3 HandState_ (7 motors, 9 pads) CDR body %zu B\n", wire.size());
}

}  // namespace
